@Configuration
@ConditionalOnProperty(name = "features.nio-cache.enabled", havingValue = "true", matchIfMissing = false)
public class NioCacheAutoConfiguration {

    @Bean
    @ConditionalOnClass(name = "java.nio.channels.AsynchronousFileChannel")
    public NioDataBufferFactory nioDataBufferFactory() {
        return new NioDataBufferFactory();
    }
}
